        def round_price(value: Any) -> float:
            return round(float(value or 0), 2)

        def specs(product: Mapping[str, Any]) -> list[Any]:
            raw_specs = product.get("specs")
            return list(raw_specs) if isinstance(raw_specs, list) and raw_specs else ["Standard"]

        def option_price(product: Mapping[str, Any], selected_spec: str) -> float:
            option_prices = product.get("optionPrices") if isinstance(product.get("optionPrices"), Mapping) else {}
            if selected_spec in option_prices:
                return round_price(option_prices[selected_spec])
            return round_price(product.get("price") or 0)

        def enrich_item(entry: Mapping[str, Any]) -> Mapping[str, Any] | None:
            product_id = str(entry.get("productId") or ((entry.get("product") or {}).get("id") if isinstance(entry.get("product"), Mapping) else "") or "")
            product = dict(entry.get("product") or products.get(product_id) or {})
            if not product:
                return None
            selected_spec = str(entry.get("selectedSpec") or (specs(product)[0] if product else ""))
            quantity = int(entry.get("quantity") or 0)
            unit_price = round_price(entry.get("unitPrice") or option_price(product, selected_spec))
            line_total = round_price(entry.get("lineTotal") or unit_price * quantity)
            normalized = {
                "id": str(entry.get("id") or ""),
                "quantity": quantity,
                "selectedSpec": selected_spec,
                "unitPrice": unit_price,
                "lineTotal": line_total,
                "product": product,
            }
            if isinstance(entry.get("review"), Mapping):
                normalized["review"] = dict(entry.get("review") or {})
            return normalized

        cart_items = [item for item in (enrich_item(entry) for entry in user_state.get("cart") or []) if item]
        subtotal = round_price(sum(float(item.get("lineTotal") or 0) for item in cart_items))
        shipping = 12 if cart_items else 0
        discount = 30 if subtotal >= 300 else 0
        cart = {
            "items": cart_items,
            "itemCount": sum(int(item.get("quantity") or 0) for item in cart_items),
            "subtotal": subtotal,
            "shipping": shipping,
            "discount": discount,
            "total": round_price(subtotal + shipping - discount),
        }

        orders = []
        reviews = []
        for raw_order in user_state.get("orders") or []:
            if not isinstance(raw_order, Mapping):
                continue
            order = dict(raw_order)
            order_items = [item for item in (enrich_item(entry) for entry in order.get("items") or []) if item]
            order["items"] = order_items
            orders.append(order)
            for item in order_items:
                review = item.get("review")
                if isinstance(review, Mapping):
                    reviews.append({
                        "productId": str((item.get("product") or {}).get("id") or ""),
                        "rating": review.get("rating"),
                        "text": review.get("review") or review.get("text") or "",
                        "orderId": order.get("id"),
                        "itemId": item.get("id"),
                    })

