    @staticmethod
    def _validate_benchmark_events(expectations: list[Any], payload: Mapping[str, Any]) -> None:
        events = list(payload.get("events") or [])
        for expected_event in expectations:
            if not isinstance(expected_event, Mapping):
                continue
            event_type = str(expected_event.get("type") or "").strip()
            matcher = dict(expected_event.get("match") or {})
            assert event_type, "benchmark event expectation missing type"
            matched = False
            for event in events:
                if str(event.get("type") or "") != event_type:
                    continue
                if all(str(event.get(key) or "") == str(value or "") for key, value in matcher.items()):
                    matched = True
                    break
            suffix = f" with {matcher}" if matcher else ""
            assert matched, f"expected benchmark event {event_type}{suffix}"

