import json
from pathlib import Path

expectations = json.loads({json.dumps(json.dumps(normalized, ensure_ascii=False))})
results = []
for item in expectations:
    path = Path(str(item.get("path") or ""))
    if not path.is_file():
        raise SystemExit(f"TEXT_ARTIFACT_NOT_FOUND:{{path}}")
    actual = path.read_text(encoding=str(item.get("encoding") or "utf-8")).replace("\\r\\n", "\\n")
    result = {{"path": str(path), "bytes": len(actual.encode("utf-8"))}}
    if "equals" in item:
        expected = str(item.get("equals") or "").replace("\\r\\n", "\\n")
        if actual.rstrip("\\n") != expected.rstrip("\\n"):
            raise SystemExit(
                "TEXT_ARTIFACT_MISMATCH:"
                + str(path)
                + ":expected="
                + repr(expected)
                + ":actual="
                + repr(actual)
            )
    for needle in item.get("contains") or []:
        if str(needle) not in actual:
            raise SystemExit(f"TEXT_ARTIFACT_MISSING_TEXT:{{path}}:{{needle}}")
    results.append(result)
print(json.dumps(results, ensure_ascii=False))
